let canvas;
let myShader;
let color1, color2;
let colors = [];
let mode = 0;

function preload() {
	myShader = createShader(vert, frag);
}
function setup() {
	canvas = createGraphics(windowWidth, windowHeight, WEBGL);
	createCanvas(windowWidth, windowHeight, WEBGL);
	canvas.noStroke();

	color1 = color("#e1ded9");
	color2 = color("#F7F0DF");
	colors.push(color("#9f9186"));
	colors.push(color("#625a55"));
	colors.push(color("#374028"));//dark green
	colors.push(color("#CAF285"));//light color
	colors.push(color("#edddd5"));
}

function draw() {
	canvas.push();
	canvas.translate(-width/2, -height/2);

	//bg
	canvas.beginShape();
		canvas.fill(color1);
		canvas.vertex(0, 0);
		canvas.vertex(width, 0);
		canvas.fill(color2);
		canvas.vertex(width, height);
		canvas.vertex(0, height);
	canvas.endShape(CLOSE);

	let time = frameCount/90;
	for(let x = 100; x < width; x+= 200) {
		let y = height;
		let counter = 0;
		while(y>0){

			//noise
			let n = 0;
			if(mode == 1)
				n = noise(abs(sin(time) + cos(x + counter)))
			else
				n = noise(time + x + counter);

			let size = n*60;
			let d = dist(x, y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
			if(d<200) size += (200-d)/5;
			let col = colors[floor(counter*302.24)%colors.length];

			//draw arrow
			canvas.beginShape();
				canvas.fill(col);
				canvas.vertex(x, y-size);
				canvas.vertex(x-size, y-2*size);
				canvas.vertex(x-size, y-size);
				canvas.fill(color1);//n * 255);
				canvas.vertex(x, y);
				canvas.fill(col);
				canvas.vertex(x+size, y-size);
				canvas.vertex(x+size, y-2*size);
			canvas.endShape(CLOSE);

			y -= size;
			counter++;
		}
	}

	canvas.pop();

	shader(myShader);
	myShader.setUniform('time', millis());
	myShader.setUniform('mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height]);
	myShader.setUniform('tex0', canvas);
	rect(0,0,width, height);
}

function mousePressed(){
	mode++;
	mode = mode%2;
}

// === Tab: shader ===
var vert=`
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

var frag=`
precision mediump float;
varying vec2 vTexCoord;
uniform sampler2D tex0;

uniform vec2 mouse;// 0 and 1
uniform float time;

float nrand( vec2 n ) {
	return fract(sin(dot(n, vec2(12.9898, 78.233)))* 43758.5453);
}

void main() {
	vec2 uv = vTexCoord;
  uv.y = 1.0 - uv.y;

	//line noise
	float noiseY = uv.y;
	float scale = 0.004;
	noiseY = fract(floor(noiseY/scale)*scale);
  noiseY = nrand(vec2(uv.x, noiseY));
	uv += vec2(0., noiseY*0.01) * mouse.y * 3.;

	vec4 color = texture2D(tex0, uv);

	//spread noise
	uv += (nrand(uv)-0.5) * 0.01;

	color = color * 0.5 + 0.5 * texture2D(tex0, uv);

	gl_FragColor = color;
}
`

